import{_ as e,o as l,c as a,ao as d}from"./chunks/framework.DpqIt34a.js";const u=JSON.parse('{"title":"libfftl C API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/libfftl.md","filePath":"reference/libfftl.md","lastUpdated":null}'),r={name:"reference/libfftl.md"};function n(i,t,o,s,f,c){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="libfftl-C-API" tabindex="-1">libfftl C API <a class="header-anchor" href="#libfftl-C-API" aria-label="Permalink to &quot;libfftl C API {#libfftl-C-API}&quot;">​</a></h1><p>The complete header is <a href="/FFTL.jl/dev/generated/libfftl_header#C-header-(fftl.h)"><code>fftl.h</code></a>. This page lists the functions and the limits; the header has the exact contracts.</p><h2 id="Functions" tabindex="-1">Functions <a class="header-anchor" href="#Functions" aria-label="Permalink to &quot;Functions {#Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">function</th><th style="text-align:left;">purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>fftl_version(buf, len)</code></td><td style="text-align:left;">the library version as <code>&quot;major.minor.patch&quot;</code></td></tr><tr><td style="text-align:left;"><code>fftl_plan_dft(rank, dims, transform_rank, region, precision, sign, threads)</code></td><td style="text-align:left;">complex DFT plan, <code>sign</code> −1 forward or +1 backward</td></tr><tr><td style="text-align:left;"><code>fftl_plan_dft_r2c(rank, dims, transform_rank, region, precision, threads)</code></td><td style="text-align:left;">real input, half spectrum out; in place uses FFTW&#39;s padded real layout</td></tr><tr><td style="text-align:left;"><code>fftl_plan_dft_c2r(rank, dims, transform_rank, region, precision, threads)</code></td><td style="text-align:left;">half spectrum in, real output, unnormalised; in place uses FFTW&#39;s padded real layout</td></tr><tr><td style="text-align:left;"><code>fftl_plan_r2r(rank, dims, transform_rank, region, kinds, precision, threads)</code></td><td style="text-align:left;">real-to-real transforms, one kind per dimension</td></tr><tr><td style="text-align:left;"><code>fftl_plan_execute(plan, out, in)</code></td><td style="text-align:left;">apply a plan of any of the four kinds; <code>out == in</code> runs in place</td></tr><tr><td style="text-align:left;"><code>fftl_plan_destroy(plan)</code></td><td style="text-align:left;">free a plan</td></tr><tr><td style="text-align:left;"><code>fftl_last_error(buf, len)</code></td><td style="text-align:left;">the message of the last failed call on this thread</td></tr></tbody></table><p>The kinds are <code>FFTL_REDFT00</code> … <code>FFTL_REDFT11</code> (DCT-I to DCT-IV), <code>FFTL_RODFT00</code> … <code>FFTL_RODFT11</code> (DST-I to DST-IV), <code>FFTL_DHT</code>, <code>FFTL_R2HC</code> and <code>FFTL_HC2R</code>.</p><h2 id="Limits" tabindex="-1">Limits <a class="header-anchor" href="#Limits" aria-label="Permalink to &quot;Limits {#Limits}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">limit</th></tr></thead><tbody><tr><td style="text-align:left;">rank</td><td style="text-align:left;">any, at least 1</td></tr><tr><td style="text-align:left;">dimension lengths</td><td style="text-align:left;">any, at least 1; lengths with large prime factors use Bluestein&#39;s algorithm</td></tr><tr><td style="text-align:left;">transform rank</td><td style="text-align:left;">0 to the rank; the region is strictly ascending, 0-based</td></tr><tr><td style="text-align:left;">precision</td><td style="text-align:left;"><code>FFTL_PRECISION_DOUBLE</code> (<code>Complex{Float64}</code>, 16 bytes) and <code>FFTL_PRECISION_SINGLE</code> (<code>Complex{Float32}</code>, 8 bytes)</td></tr><tr><td style="text-align:left;">sign</td><td style="text-align:left;">−1 or +1 for complex plans</td></tr><tr><td style="text-align:left;">normalisation</td><td style="text-align:left;">none; the backward transform multiplies by the number of transformed elements</td></tr><tr><td style="text-align:left;">threads</td><td style="text-align:left;">the value is stored per plan; the worker pool is fixed when the library is built (<code>FFTL_THREADS</code>). More threads than workers run on the workers that exist</td></tr><tr><td style="text-align:left;">memory</td><td style="text-align:left;">bounded by the available memory and by 64-bit element offsets</td></tr><tr><td style="text-align:left;">concurrency</td><td style="text-align:left;">different plans execute in parallel; one plan on one thread at a time; destroying a plan during its execution is not allowed</td></tr><tr><td style="text-align:left;">number types</td><td style="text-align:left;"><code>float</code> and <code>double</code> only; no GPU, no generic number types</td></tr></tbody></table><h2 id="Build-and-size" tabindex="-1">Build and size <a class="header-anchor" href="#Build-and-size" aria-label="Permalink to &quot;Build and size {#Build-and-size}&quot;">​</a></h2><p>On macOS (arm64), the build output in <code>libfftl/build/lib</code> is 23 MB: the library (14 MB) and the Julia runtime next to it (10 MB). No Julia installation is needed to run a program that links it. The build needs Julia 1.12 or newer with <code>juliac</code>. See <a href="/FFTL.jl/dev/howto/libfftl#C-library-(libfftl)">C library (libfftl)</a> for the build variables.</p><h2 id="Errors" tabindex="-1">Errors <a class="header-anchor" href="#Errors" aria-label="Permalink to &quot;Errors {#Errors}&quot;">​</a></h2><p>Constructors return a negative handle on failure; <code>fftl_plan_execute</code> and <code>fftl_plan_destroy</code> return −1 on a bad handle or a failed execution. The reason is in <code>fftl_last_error</code>, which keeps its message until the next failed call on the same thread.</p>',11)])])}const p=e(r,[["render",n]]);export{u as __pageData,p as default};
